  Download,
  Calendar,
  TrendingUp,
  Clock,
  CheckCircle,
  AlertCircle,
} from "lucide-react";
import { DashboardHeader } from "../components/dashboard/DashboardHeader";
import { ProjectCard } from "../components/shared/ProjectCard";
import { DocumentCard } from "../components/shared/DocumentCard";
import { useAuth } from "../contexts/AuthContext";
import { useDashboardData } from "../hooks/useDashboardData";
import { documentService } from "../services/documentService";
import { formatDate, formatCurrency } from "../utils/formatters";

const ClientDashboard = () => {
  const { user } = useAuth();
  const { projects, documents, loading, error, refetch } = useDashboardData();
  const [activeTab, setActiveTab] = useState("overview");

  const handleDownloadDocument = async (document) => {
    try {
      const blob = await documentService.download(document._id);
      const url = window.URL.createObjectURL(blob);
      const a = window.document.createElement("a");
      a.href = url;
      a.download = document.file_name;
      window.document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      window.document.body.removeChild(a);
    } catch (error) {
      alert("Error al descargar el documento");
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-green-500"></div>
      </div>
    );
  }

  if (error) {
 
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-600 text-xl mb-4">Error al cargar los datos</p>
          <Button onClick={refetch}>Reintentar</Button>
        </div>
      </div>
    );
  }

  // Calcular estadísticas
  const activeProjects = projects.filter(p => p.status === 'in_progress').length;
  const completedProjects = projects.filter(p => p.status === 'completed').length;
  const totalProjects = projects.length;
  const projectCompletionRate = totalProjects > 0 
    ? Math.round((completedProjects / totalProjects) * 100) 
    : 0;

  return (
    <div className="min-h-screen bg-gray-50">
      <DashboardHeader />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Bienvenida personalizada */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">
            Bienvenido, {user?.full_name}
          </h1>
          <p className="text-gray-600 mt-1">
            {user?.client_id?.company_name || 'Panel de Cliente'}
          </p>
        </div>

        {/* Tarjetas de estadísticas */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">Total Proyectos</p>
                  <p className="text-2xl font-bold text-gray-900">{totalProjects}</p>
                </div>
                <Briefcase className="w-8 h-8 text-blue-500" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">En Progreso</p>
                  <p className="text-2xl font-bold text-gray-900">{activeProjects}</p>
                </div>
                <TrendingUp className="w-8 h-8 text-green-500" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">Completados</p>
                  <p className="text-2xl font-bold text-gray-900">{completedProjects}</p>
                </div>
                <CheckCircle className="w-8 h-8 text-purple-500" />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">Documentos</p>
                  <p className="text-2xl font-bold text-gray-900">{documents.length}</p>
                </div>
                <FileText className="w-8 h-8 text-orange-500" />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Progreso general */}
        <Card className="mb-8">
          <CardHeader>
            <CardTitle>Progreso de Proyectos</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-gray-600">Tasa de finalización</span>
                <span className="font-semibold">{projectCompletionRate}%</span>
              </div>
              <Progress value={projectCompletionRate} className="h-3" />
              <div className="flex justify-between text-xs text-gray-500">
                <span>{completedProjects} completados</span>
                <span>{activeProjects} en progreso</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Tabs principales */}
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="grid w-full grid-cols-2 mb-6">
            <TabsTrigger value="overview">
              <Briefcase className="w-4 h-4 mr-2" />
              Mis Proyectos
            </TabsTrigger>
            <TabsTrigger value="documents">
              <FileText className="w-4 h-4 mr-2" />
              Mis Documentos
            </TabsTrigger>
          </TabsList>

          {/* Proyectos */}
          <TabsContent value="overview" className="space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-bold text-gray-900">Mis Proyectos</h2>
            </div>

            {projects.length === 0 ? (
              <Card>
                <CardContent className="text-center py-12">
                  <Briefcase className="w-16 h-16 mx-auto text-gray-400 mb-4" />
                  <p className="text-gray-600">
                    No hay proyectos asignados actualmente
                  </p>
                  <p className="text-sm text-gray-500 mt-2">
                    Cuando se te asignen proyectos, aparecerán aquí
                  </p>
                </CardContent>
              </Card>
            ) : (
              <div className="grid gap-4">
                {projects.map((project) => (
                  <ProjectCard
                    key={project._id}
                    project={project}
                    onUpdate={refetch}
                  />
                ))}
              </div>
            )}
          </TabsContent>

          {/* Documentos */}
          <TabsContent value="documents" className="space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-2xl font-bold text-gray-900">Mis Documentos</h2>
              <Badge variant="outline" className="text-sm">
                {documents.length} documento(s)
              </Badge>
            </div>

            {documents.length === 0 ? (
              <Card>
                <CardContent className="text-center py-12">
                  <FileText className="w-16 h-16 mx-auto text-gray-400 mb-4" />
                  <p className="text-gray-600">No hay documentos disponibles</p>
                  <p className="text-sm text-gray-500 mt-2">
                    Los documentos de tus proyectos aparecerán aquí
                  </p>
                </CardContent>
              </Card>
            ) : (
              <div className="grid gap-4">
                {documents.map((document) => (
                  <DocumentCard
                    key={document._id}
                    document={document}
                    onDownload={handleDownloadDocument}
                  />
                ))}
              </div>
            )}
          </TabsContent>
        </Tabs>

        {/* Ayuda y soporte */}
        <Card className="mt-8 bg-gradient-to-r from-green-50 to-emerald-50 border-green-200">
          <CardContent className="p-6">
            <div className="flex items-start space-x-4">
              <AlertCircle className="w-6 h-6 text-green-600 flex-shrink-0 mt-1" />
              <div>
                <h3 className="font-semibold text-gray-900 mb-1">
                  ¿Necesitas ayuda?
                </h3>
                <p className="text-sm text-gray-600 mb-3">
                  Si tienes dudas sobre tus proyectos o necesitas documentación adicional, 
                  contacta a tu consultor asignado.
                </p>
                <div className="flex flex-wrap gap-2">
                  <Button variant="outline" size="sm">
                    Contactar Consultor
                  </Button>
                  <Button variant="outline" size="sm">
                    Ver FAQ
                  </Button>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </main>
    </div>
  );
};

export default ClientDashboard;
